-- =====================================================================
-- BACKSTREET · step 2 of 3: game content (districts, jobs, fighters, 1028 items, 18 companies, 31 homes).
-- Generated by scripts/gen-sql.mjs. Safe to re-run: it updates rows in place.
-- =====================================================================
on conflict (id) do update set name=excluded.name,lvl=excluded.lvl,fare=excluded.fare,sort=excluded.sort;
on conflict (id) do update set name=excluded.name,district=excluded.district,lvl=excluded.lvl,grit=excluded.grit,base=excluded.base,cash_min=excluded.cash_min,cash_max=excluded.cash_max,xp=excluded.xp,loot=excluded.loot,sort=excluded.sort;

on conflict (id) do update set name=excluded.name,district=excluded.district,lvl=excluded.lvl,power=excluded.power,cash_min=excluded.cash_min,cash_max=excluded.cash_max,xp=excluded.xp,loot=excluded.loot,sort=excluded.sort;

on conflict (id) do update set name=excluded.name,cat=excluded.cat,rarity=excluded.rarity,value=excluded.value,fx=excluded.fx,effect=excluded.effect,shop=excluded.shop,supply=excluded.supply,season=excluded.season;

on conflict (id) do update set name=excluded.name,cat=excluded.cat,rarity=excluded.rarity,value=excluded.value,fx=excluded.fx,effect=excluded.effect,shop=excluded.shop,supply=excluded.supply,season=excluded.season;

on conflict (id) do update set name=excluded.name,cat=excluded.cat,rarity=excluded.rarity,value=excluded.value,fx=excluded.fx,effect=excluded.effect,shop=excluded.shop,supply=excluded.supply,season=excluded.season;

on conflict (id) do update set name=excluded.name,cat=excluded.cat,rarity=excluded.rarity,value=excluded.value,fx=excluded.fx,effect=excluded.effect,shop=excluded.shop,supply=excluded.supply,season=excluded.season;

on conflict (id) do update set name=excluded.name,cat=excluded.cat,rarity=excluded.rarity,value=excluded.value,fx=excluded.fx,effect=excluded.effect,shop=excluded.shop,supply=excluded.supply,season=excluded.season;

on conflict (ticker) do update set name=excluded.name,sector=excluded.sector,twin=excluded.twin,vol=excluded.vol,perk_shares=excluded.perk_shares,perk=excluded.perk,perk_desc=excluded.perk_desc,sort=excluded.sort;

-- Homes: 31 steps from a doorway to the Moon.
on conflict (id) do update set name=excluded.name,price=excluded.price,mood=excluded.mood,stamina=excluded.stamina,lvl=excluded.lvl,blurb=excluded.blurb,sort=excluded.sort,perks=excluded.perks;
delete from game.properties where id not in ('rough','box','tent','shelter','caravan','van','couch','student','bedsit','boarding','flat','container','unit','townhouse','villa','houseboat','apartment','loft','bungalow','penthouse','gated','mansion','vineyard','estate','lodge','yacht','castle','tower','lighthouse','bridge','moon');
update game.players set property = 'rough' where property not in (select id from game.properties);
-- Mood and stamina limits are the base for your level plus what your home adds.
update game.players p set max_mood = 250 + (p.level / 3) * 25 + h.mood, max_stamina = 100 + h.stamina from game.properties h where h.id = p.property;

-- Careers: 6 careers, 10 ranks each.
on conflict (id) do update set name=excluded.name,perk=excluded.perk,max=excluded.max,wage=excluded.wage,blurb=excluded.blurb,ranks=excluded.ranks,sort=excluded.sort;
on conflict (rank) do update set shifts=excluded.shifts,lvl=excluded.lvl;

-- Vehicles: 16, on foot to a private submarine.
on conflict (id) do update set name=excluded.name,price=excluded.price,lvl=excluded.lvl,blurb=excluded.blurb,sort=excluded.sort,perks=excluded.perks;
delete from game.vehicles where id not in ('foot','bike','scooter','moped','hatch','ute','roadbike','muscle','suv','sports','limo','hyper','heli','seaplane','jet','sub');
update game.players set vehicle = 'foot' where vehicle not in (select id from game.vehicles);

-- Medals: 136.
on conflict (id) do update set stat=excluded.stat,at=excluded.at,name=excluded.name,what=excluded.what,tier=excluded.tier,tiers=excluded.tiers,sort=excluded.sort;

-- Story missions: 8 stories, 40 missions.
on conflict (chain,step) do update set chain_name=excluded.chain_name,who=excluded.who,lvl=excluded.lvl,blurb=excluded.blurb,title=excluded.title,story=excluded.story,
  done_text=excluded.done_text,k=excluded.k,n=excluded.n,reward=excluded.reward,sort=excluded.sort;

-- Seasonal events: 5.
on conflict (id) do update set name=excluded.name,blurb=excluded.blurb,from_m=excluded.from_m,from_d=excluded.from_d,to_m=excluded.to_m,to_d=excluded.to_d,points=excluded.points,icon=excluded.icon;

-- Companies players can start: 10 kinds.
on conflict (id) do update set name=excluded.name,cost=excluded.cost,lvl=excluded.lvl,base=excluded.base,perk=excluded.perk,max=excluded.max,blurb=excluded.blurb,sort=excluded.sort;
