insert into game.properties(id,name,price,mood,stamina,lvl,blurb,sort,perks) values
('rough','Sleeping rough in a doorway',0,0,0,1,'A sleeping bag that was never quite dry, and seagulls with opinions.',1,'{"regen":-0.25}'::jsonb),
('box','A cardboard box behind the fish market',60,20,0,1,'Fridge-sized, with a flap for a door. It smells of fish, but it''s yours.',2,'{"regen":-0.15}'::jsonb),
('tent','A tent under the motorway',500,50,0,1,'Keeps the rain off. Mostly. The traffic noise is free.',3,'{}'::jsonb),
('shelter','A bunk at the night shelter',1200,70,0,1,'Lights out at ten, a hot breakfast at six, and someone always snoring.',4,'{"daily":{"item":"pie","qty":1}}'::jsonb),
('caravan','A rusty caravan in a paddock',3000,90,0,2,'It hasn''t moved since 1987. Neither has the farmer''s dog.',5,'{"regen":0.02}'::jsonb),
('van','A campervan with one working door',6000,110,0,2,'Home is wherever you park it, until the council tows it.',6,'{"travel_disc":0.5}'::jsonb),
('couch','Your mate''s couch',9000,130,3,3,'You pay rent in cash and beer. He pays you back in beer.',7,'{"daily":{"item":"lager","qty":1}}'::jsonb),
('student','A room in a student flat',13000,150,5,3,'Five flatmates, one bathroom, and a gym membership someone forgot to cancel.',8,'{"gym":0.03}'::jsonb),
('bedsit','Bedsit above the dairy',18000,180,5,4,'One room, one window, one neighbour who practises the trumpet. The dairy owner leaves you pies.',9,'{"regen":0.05,"daily":{"item":"pie","qty":2}}'::jsonb),
('boarding','A room at the boarding house',26000,210,8,4,'Mrs Ngata runs a tight ship and patches up her lodgers when they come home bleeding.',10,'{"regen":0.05,"hosp":0.05}'::jsonb),
('flat','Flat on the Waterfront',45000,250,10,5,'Two rooms and a view of the ferry terminal, if you lean out. And a lock.',11,'{"regen":0.05,"mug":0.2,"daily":{"item":"lager","qty":1}}'::jsonb),
('container','A converted shipping container',70000,290,12,5,'Insulated, wired and parked at the Docks, where you hear everything first.',12,'{"regen":0.05,"mug":0.2,"job":2}'::jsonb),
('unit','A two-bedroom unit',100000,340,14,6,'Carpet, a carport and a spare room that''s become a home gym.',13,'{"regen":0.08,"mug":0.2,"hosp":0.1,"gym":0.03}'::jsonb),
('townhouse','Old Town townhouse',150000,400,16,6,'Brick walls, a proper kitchen and a first-aid cupboard that is actually stocked.',14,'{"regen":0.1,"mug":0.25,"hosp":0.15,"daily":{"item":"med","qty":1}}'::jsonb),
('villa','A villa with a veranda',250000,460,18,7,'Weatherboards, a lemon tree and a veranda made for slow evenings.',15,'{"regen":0.1,"mug":0.25,"hosp":0.15,"gym":0.05,"daily":{"item":"lager","qty":2}}'::jsonb),
('houseboat','A houseboat in the marina',400000,530,20,8,'It rocks you to sleep and gets you across the harbour for half the fare.',16,'{"regen":0.1,"mug":0.25,"hosp":0.15,"travel_disc":0.5,"daily":{"item":"drink","qty":1}}'::jsonb),
('apartment','Harbour apartment',600000,600,25,9,'Floor-to-ceiling glass, a gym downstairs and a doorman who knows your name.',17,'{"regen":0.1,"mug":0.3,"hosp":0.15,"heat":0.15,"listings":5,"daily":{"item":"drink","qty":1}}'::jsonb),
('loft','A warehouse loft in the Docks',900000,680,28,10,'Exposed brick, a freight lift, and a view straight onto the container yard.',18,'{"regen":0.12,"mug":0.3,"hosp":0.15,"heat":0.15,"listings":5,"job":3,"daily":{"item":"drink","qty":1}}'::jsonb),
('bungalow','A hilltop bungalow',1400000,760,32,11,'The whole harbour spread out below, and a long drive nobody comes up uninvited.',19,'{"regen":0.12,"mug":0.3,"hosp":0.2,"heat":0.2,"listings":5,"gym":0.05,"daily":{"item":"drink","qty":1,"cash":2000}}'::jsonb),
('penthouse','Heights penthouse',2500000,900,40,13,'The top floor. Private lift, roof terrace, and a doorman who forgets faces for a fee.',20,'{"regen":0.15,"mug":0.35,"hosp":0.2,"heat":0.25,"listings":5,"daily":{"item":"drink","qty":2}}'::jsonb),
('gated','A gated mansion',4500000,1100,48,14,'Cameras on every corner, a guard at the gate and a pool nobody swims in.',21,'{"regen":0.18,"mug":0.45,"hosp":0.22,"heat":0.25,"listings":8,"gym":0.07,"daily":{"item":"drink","qty":2,"cash":4000}}'::jsonb),
('mansion','Clifftop mansion',8000000,1300,55,16,'Twelve bedrooms, a wine cellar, a panic room, and staff who never ask questions.',22,'{"regen":0.2,"mug":0.5,"hosp":0.25,"heat":0.3,"listings":10,"gym":0.07,"daily":{"item":"smallbox","qty":1}}'::jsonb),
('vineyard','A vineyard estate',14000000,1550,62,18,'Forty hectares of pinot noir and a cellar door that does very well on weekends.',23,'{"regen":0.2,"mug":0.5,"hosp":0.25,"heat":0.3,"listings":10,"gym":0.08,"daily":{"item":"lager","qty":5,"cash":8000}}'::jsonb),
('estate','Island estate',25000000,1800,70,20,'Your own island in the harbour, with a jetty, a helipad and a boat that takes you anywhere for free.',24,'{"regen":0.2,"mug":0.55,"hosp":0.3,"heat":0.35,"listings":10,"gym":0.08,"travel_free":true,"daily":{"item":"smallbox","qty":1,"cash":10000}}'::jsonb),
('lodge','A private ski lodge',45000000,2100,78,22,'Your own mountain, your own lift, and a fireplace you could park a car in.',25,'{"regen":0.22,"mug":0.6,"hosp":0.32,"heat":0.38,"listings":12,"gym":0.1,"travel_free":true,"daily":{"item":"smallbox","qty":1,"cash":15000}}'::jsonb),
('yacht','The superyacht Nightjar',80000000,2400,85,24,'Ninety metres of polished teak with a submarine in the garage. You can be anywhere in the city in seconds.',26,'{"regen":0.25,"mug":0.65,"hosp":0.35,"heat":0.4,"listings":15,"gym":0.1,"travel_free":true,"travel_fast":true,"daily":{"item":"crate","qty":1,"cash":20000}}'::jsonb),
('castle','A castle in the hills',140000000,2800,92,26,'Shipped stone by stone from Scotland, with a moat you had to dig yourself.',27,'{"regen":0.28,"mug":0.7,"hosp":0.38,"heat":0.45,"listings":15,"gym":0.12,"job":5,"travel_free":true,"travel_fast":true,"daily":{"item":"crate","qty":1,"cash":30000}}'::jsonb),
('tower','Backstreet Tower',250000000,3200,100,28,'Sixty floors of glass in the middle of the skyline, with your name lit up on the top. Forty floors of tenants pay you rent.',28,'{"regen":0.3,"mug":0.75,"hosp":0.4,"heat":0.5,"listings":20,"gym":0.12,"job":5,"travel_free":true,"travel_fast":true,"skyline":true,"daily":{"item":"safebox","qty":1,"cash":50000}}'::jsonb),
('lighthouse','The lighthouse island',400000000,3600,110,31,'The old lighthouse at the harbour mouth. Every ship that comes in passes under your window.',29,'{"regen":0.35,"mug":0.8,"hosp":0.42,"heat":0.55,"listings":20,"gym":0.15,"job":6,"travel_free":true,"travel_fast":true,"skyline":true,"daily":{"item":"safebox","qty":1,"cash":75000}}'::jsonb),
('bridge','The Harbour Bridge. All of it.',650000000,4100,125,34,'You bought the bridge. Every car that crosses pays you a toll, and you live in the control room at the top of the arch.',30,'{"regen":0.4,"mug":0.85,"hosp":0.45,"heat":0.6,"listings":25,"gym":0.15,"job":7,"travel_free":true,"travel_fast":true,"skyline":true,"daily":{"item":"safebox","qty":1,"cash":150000}}'::jsonb),
('moon','A penthouse on the Moon',1000000000,5000,150,38,'Low gravity, no police, and the best view of Backstreet anyone has ever had. The commute is surprisingly short.',31,'{"regen":0.5,"mug":0.9,"hosp":0.5,"heat":0.6,"listings":25,"gym":0.2,"job":8,"travel_free":true,"travel_fast":true,"skyline":true,"daily":{"item":"safebox","qty":2,"cash":250000}}'::jsonb)
insert into game.careers(id,name,perk,max,wage,blurb,ranks,sort) values
('kitchen','Hospitality','regen',0.12,60,'Long shifts, free meals, and you hear everything that''s said across the bar.',array['Dishwasher','Kitchen hand','Barista','Line cook','Bartender','Sous chef','Head chef','Restaurant manager','Restaurateur','Celebrity chef'],1),
('security','Security','mug',0.3,70,'You learn where the cameras point, and how to stand so nobody tries anything.',array['Night watch','Door staff','Bouncer','Mobile patrol','Close protection','Team leader','Security manager','Head of security','Security consultant','Private army'],2),
('docks','The Docks','gym',0.15,75,'Heavy lifting builds heavy shoulders. And containers sometimes fall open.',array['Labourer','Lasher','Forklift driver','Stevedore','Straddle driver','Crane operator','Foreman','Yard manager','Port captain','Harbourmaster'],3),
('medicine','Medicine','hosp',0.35,80,'Patch up the city by day. Know exactly how to patch yourself up by night.',array['Hospital orderly','Healthcare assistant','Paramedic','Nurse','Charge nurse','Junior doctor','Registrar','Consultant','Head of A&E','Chief of surgery'],4),
('law','Law','jail',0.35,85,'Learn the rules so well you know exactly how long to bend them.',array['Legal clerk','Paralegal','Law student','Junior lawyer','Defence lawyer','Senior associate','Partner','Senior partner','Queen''s Counsel','Judge'],5),
('finance','Finance','job',6,90,'Spreadsheets, suits and a very good sense of who has money and where they keep it.',array['Bank teller','Loan officer','Analyst','Trader','Senior trader','Fund manager','Investment banker','Partner','Managing director','Hedge fund boss'],6)
