insert into game.vehicles(id,name,price,lvl,blurb,sort,perks) values
('foot','On foot',0,1,'Your own two feet and a bus pass that expired in March.',1,'{}'::jsonb),
('bike','A stolen bike',150,1,'Someone''s going to miss this. Not your problem.',2,'{"travel_time":0.05}'::jsonb),
('scooter','An e-scooter',900,2,'Silent, quick, and abandoned on every corner. This one''s charged.',3,'{"travel_time":0.1}'::jsonb),
('moped','A 50cc moped',3500,3,'It sounds like a hairdryer and goes about as fast. Still beats walking.',4,'{"travel_time":0.15,"travel_disc":0.1}'::jsonb),
('hatch','A 1998 hatchback',9000,4,'Rust, a tape deck and a boot big enough for most of a shop''s stock.',5,'{"travel_time":0.2,"travel_disc":0.25,"job":1}'::jsonb),
('ute','A farm ute',22000,5,'Dog box on the back, mud on everything, and nobody looks twice at it.',6,'{"travel_time":0.25,"travel_disc":0.3,"job":1,"heat":0.03}'::jsonb),
('roadbike','A road motorbike',55000,7,'Through the traffic and gone before the sirens get started.',7,'{"travel_time":0.35,"travel_disc":0.35,"job":2,"heat":0.05}'::jsonb),
('muscle','A muscle car',120000,9,'Big engine, bigger noise. It makes an exit an event.',8,'{"travel_time":0.4,"travel_disc":0.4,"job":3,"heat":0.05}'::jsonb),
('suv','A blacked-out SUV',300000,11,'Tinted windows, run-flat tyres and room for a whole crew.',9,'{"travel_time":0.45,"travel_disc":0.5,"job":3,"mug":0.1,"heat":0.1}'::jsonb),
('sports','An Italian sports car',750000,13,'Red, low and loud. Every getaway driver''s dream.',10,'{"travel_time":0.5,"travel_disc":0.6,"job":4,"heat":0.1}'::jsonb),
('limo','An armoured limousine',1800000,15,'Bulletproof glass, a driver called Bruce and a minibar.',11,'{"travel_time":0.5,"travel_disc":0.7,"job":4,"mug":0.2,"hosp":0.05,"heat":0.1}'::jsonb),
('hyper','A hypercar',4500000,18,'Zero to a hundred before the alarm finishes its first beep.',12,'{"travel_time":0.6,"travel_disc":0.8,"job":5,"heat":0.15}'::jsonb),
('heli','A helicopter',12000000,21,'Traffic is other people''s problem now.',13,'{"travel_time":0.7,"travel_free":true,"job":6,"heat":0.2}'::jsonb),
('seaplane','A seaplane',30000000,24,'Lands on the harbour, takes off from anywhere, and the coastguard can''t keep up.',14,'{"travel_time":0.75,"travel_free":true,"job":6,"heat":0.25,"mug":0.2}'::jsonb),
('jet','A private jet',75000000,28,'Wheels up whenever you say. Customs is a formality.',15,'{"travel_time":0.8,"travel_free":true,"job":7,"heat":0.3,"mug":0.25}'::jsonb),
('sub','A private submarine',160000000,33,'Nobody follows you underwater. Nobody even knows you''ve left.',16,'{"travel_time":0.85,"travel_free":true,"job":8,"heat":0.4,"mug":0.3}'::jsonb)
