insert into game.missions(chain,step,chain_name,who,lvl,blurb,title,story,done_text,k,n,reward,sort) values
('rose',1,'Aunty Rose''s dairy','Aunty Rose',1,'Someone keeps smashing the window of the dairy on the corner. Aunty Rose has fed half the Waterfront at some point, including you.','Ears to the ground','"Third window this month, love." Aunty Rose sweeps glass off the step. "Nobody tells me anything. They''ll tell you." Do a few jobs around the Waterfront and listen.','Everyone''s heard the same thing: a kid on a bike, paid by someone in Old Town.','job',3,'{"cash":300,"xp":10}'::jsonb,1),
('rose',2,'Aunty Rose''s dairy','Aunty Rose',1,'Someone keeps smashing the window of the dairy on the corner. Aunty Rose has fed half the Waterfront at some point, including you.','The kid on the bike','The corner kid has been flashing new sneakers. Have a quiet word with him.','He gives up a name before you''ve finished asking: Mack, who fences out of the pawn shop in Old Town.','fight:corner_kid',1,'{"cash":500,"item":"lager","qty":2}'::jsonb,1),
('rose',3,'Aunty Rose''s dairy','Aunty Rose',1,'Someone keeps smashing the window of the dairy on the corner. Aunty Rose has fed half the Waterfront at some point, including you.','Old Town','Mack doesn''t come to the Waterfront. You''ll have to go to him.','The pawn shop has Rose''s stolen till in the window, priced at $40.','travel:old',1,'{"cash":400,"xp":15}'::jsonb,1),
('rose',4,'Aunty Rose''s dairy','Aunty Rose',1,'Someone keeps smashing the window of the dairy on the corner. Aunty Rose has fed half the Waterfront at some point, including you.','Mack''s muscle','Mack laughs at you and sends out the man who collects his debts.','Mack hands back the till, then the money, then an apology he clearly doesn''t mean.','fight:debt_collector',1,'{"cash":1500,"xp":40}'::jsonb,1),
('rose',5,'Aunty Rose''s dairy','Aunty Rose',1,'Someone keeps smashing the window of the dairy on the corner. Aunty Rose has fed half the Waterfront at some point, including you.','A proper feed','Aunty Rose insists you sit down and eat something before you go anywhere.','"You''re a good one," she says, and slides a parcel across the counter. "Found it in the stockroom. Don''t open it here."','use',1,'{"cash":2000,"item":"smallbox","qty":1,"xp":50}'::jsonb,1),
('ngata',1,'Mrs Ngata''s lodger','Mrs Ngata',1,'The boarding-house landlady has seen a lot of people come in off the street. She thinks you might actually make it.','Off the pavement','"You can''t sleep in my doorway forever." Mrs Ngata hands you a flyer for a tent sale. Get yourself somewhere to sleep.','It''s not much, but it''s yours. Mrs Ngata nods once, which from her is a standing ovation.','home',1,'{"cash":500,"xp":10}'::jsonb,2),
('ngata',2,'Mrs Ngata''s lodger','Mrs Ngata',1,'The boarding-house landlady has seen a lot of people come in off the street. She thinks you might actually make it.','A real job','"Money from jobs comes and goes. Get a wage." Pick a career and work a shift.','Your first payslip. Mrs Ngata pins a copy on her fridge.','shift',1,'{"cash":800,"xp":15}'::jsonb,2),
('ngata',3,'Mrs Ngata''s lodger','Mrs Ngata',1,'The boarding-house landlady has seen a lot of people come in off the street. She thinks you might actually make it.','Get strong','"Half the street will try to take what you''ve got. Make it hard for them." Train at the gym.','You can feel the difference. So can the next person who tries something.','train',20,'{"cash":1000,"item":"drink","qty":2}'::jsonb,2),
('ngata',4,'Mrs Ngata''s lodger','Mrs Ngata',1,'The boarding-house landlady has seen a lot of people come in off the street. She thinks you might actually make it.','Wheels','"Stop walking everywhere, you look like a tourist." Get yourself something with wheels.','She makes you take her to the supermarket in it. It''s the least you can do.','vehicle',1,'{"cash":2000,"xp":40}'::jsonb,2),
('ngata',5,'Mrs Ngata''s lodger','Mrs Ngata',1,'The boarding-house landlady has seen a lot of people come in off the street. She thinks you might actually make it.','Moving up','"Now get out of my sight and get a proper place." Climb another two steps up the home ladder.','She hugs you at the door and tells you to visit. You will.','home',2,'{"cash":5000,"item":"smallbox","qty":1,"xp":80}'::jsonb,2),
('kerr',1,'Inspector Kerr''s offer','Detective Inspector Huia Kerr',5,'A detective with a long memory wants something from you. Saying no doesn''t seem to be one of the options.','A quiet coffee','Kerr buys you a flat white and slides a folder across the table. "Bigger fish than you are swimming in this harbour. Help me catch them." First, prove you''re useful: spring three people from the cells so they owe you.','Three grateful ex-prisoners, three new sources. Kerr is pleased.','bust',3,'{"cash":1500,"xp":40}'::jsonb,3),
('kerr',2,'Inspector Kerr''s offer','Detective Inspector Huia Kerr',5,'A detective with a long memory wants something from you. Saying no doesn''t seem to be one of the options.','Follow the money','"The phone scams in Old Town all pay into one account." Run a phone scam yourself and get inside the operation.','You find the account details on a sticky note. Criminals are terrible with passwords.','job:scam',2,'{"cash":3000,"xp":60}'::jsonb,3),
('kerr',3,'Inspector Kerr''s offer','Detective Inspector Huia Kerr',5,'A detective with a long memory wants something from you. Saying no doesn''t seem to be one of the options.','The bikie problem','"The account belongs to the bikies. Their enforcer moves the cash." Take him off the board.','He has a ledger in his jacket. Kerr''s hands actually shake when you give it to her.','fight:bikie_enforcer',1,'{"cash":5000,"xp":90}'::jsonb,3),
('kerr',4,'Inspector Kerr''s offer','Detective Inspector Huia Kerr',5,'A detective with a long memory wants something from you. Saying no doesn''t seem to be one of the options.','Down to the Docks','"The ledger points to the Docks. I can''t go down there without a warrant. You can."','The container numbers in the ledger match the yard. All of them.','travel:docks',1,'{"cash":3000,"xp":60}'::jsonb,3),
('kerr',5,'Inspector Kerr''s offer','Detective Inspector Huia Kerr',5,'A detective with a long memory wants something from you. Saying no doesn''t seem to be one of the options.','The dock boss','"End it."','Kerr makes the arrests. Your name never appears in the paperwork. "We''re even," she says. You both know you''re not.','fight:dock_boss',1,'{"cash":15000,"item":"crate","qty":1,"xp":200}'::jsonb,3),
('pete',1,'Old Pete''s last voyage','Old Pete, the harbourmaster',8,'The harbourmaster has worked the Docks for forty years and wants one last score before he retires.','Heavy lifting','"I need someone who can carry things and keep their mouth shut." Do warehouse jobs in the Docks.','Pete watches from the crane cab. He likes what he sees.','job:ware',3,'{"cash":6000,"xp":80}'::jsonb,4),
('pete',2,'Old Pete''s last voyage','Old Pete, the harbourmaster',8,'The harbourmaster has worked the Docks for forty years and wants one last score before he retires.','Container 947','"There''s a container I''ve been not-noticing for eleven years. Tonight it moves." Smuggle it out.','Inside: crates of old harbour charts and one locked chest.','job:smug',2,'{"cash":12000,"xp":120}'::jsonb,4),
('pete',3,'Old Pete''s last voyage','Old Pete, the harbourmaster',8,'The harbourmaster has worked the Docks for forty years and wants one last score before he retires.','Company','The Kingpin''s people have noticed. They want the chest.','The Kingpin limps off, promising this isn''t over. Pete laughs until he coughs.','fight:the_kingpin',1,'{"cash":20000,"xp":200}'::jsonb,4),
('pete',4,'Old Pete''s last voyage','Old Pete, the harbourmaster',8,'The harbourmaster has worked the Docks for forty years and wants one last score before he retires.','Sea legs','"We sail at dawn. Buy something useful at the market for the trip."','Pete approves of nothing you bought, but loads it all anyway.','market',2,'{"cash":8000,"xp":80}'::jsonb,4),
('pete',5,'Old Pete''s last voyage','Old Pete, the harbourmaster',8,'The harbourmaster has worked the Docks for forty years and wants one last score before he retires.','The chest','"Open it."','Gold sovereigns, a ship''s bell and a will leaving everything to whoever helped him open it. Pete retires to the Coromandel. He sends you a postcard every Christmas.','use',1,'{"cash":40000,"item":"safebox","qty":1,"xp":300}'::jsonb,4),
('casino',1,'The house always wins','Sal, the pit boss',12,'The pit boss at the casino on the pier owes the wrong people. He has a plan to pay them back, and it involves you.','Learn the floor','"Watch the tables. Watch the guards. Watch me." Pull jobs around the Docks while Sal maps the casino.','Sal has drawn the whole floor plan on the back of a betting slip.','job',10,'{"cash":10000,"xp":100}'::jsonb,5),
('casino',2,'The house always wins','Sal, the pit boss',12,'The pit boss at the casino on the pier owes the wrong people. He has a plan to pay them back, and it involves you.','Seed money','"I need a stake to get the high rollers interested." Earn it.','Sal takes the cash and promises to double it. He actually does, which surprises everyone.','jobcash',60000,'{"cash":15000,"xp":120}'::jsonb,5),
('casino',3,'The house always wins','Sal, the pit boss',12,'The pit boss at the casino on the pier owes the wrong people. He has a plan to pay them back, and it involves you.','The security chief','The head of casino security has been asking questions. Make sure she''s in A&E on the night.','Word gets round that you''re not someone to cross. Security takes the night off.','fight_win',5,'{"cash":12000,"xp":140}'::jsonb,5),
('casino',4,'The house always wins','Sal, the pit boss',12,'The pit boss at the casino on the pier owes the wrong people. He has a plan to pay them back, and it involves you.','The vault','"Tonight. Three dials, four minutes."','Sal pays his debts and keeps a little extra. So do you.','job:vault',3,'{"cash":50000,"item":"crate","qty":1,"xp":300}'::jsonb,5),
('casino',5,'The house always wins','Sal, the pit boss',12,'The pit boss at the casino on the pier owes the wrong people. He has a plan to pay them back, and it involves you.','Lie low','"Spend some money. Look legitimate." Buy shares on the exchange.','Your stockbroker calls you ''a person of means''. Sal opens a small bar in Old Town.','stock',3,'{"cash":30000,"xp":200}'::jsonb,5),
('developer',1,'The Developer','The Developer',15,'A man in a very good suit is buying up Old Town to knock it down. Aunty Rose''s dairy is on his list.','Meet the money','The Developer throws a party in the Heights every Friday. Get in.','You overhear the plan: demolition starts next month, Aunty Rose''s dairy first.','job:party',3,'{"cash":30000,"xp":200}'::jsonb,6),
('developer',2,'The Developer','The Developer',15,'A man in a very good suit is buying up Old Town to knock it down. Aunty Rose''s dairy is on his list.','His muscle','His private security made Rose cry. Deal with them.','Their radios go quiet. The Developer starts sleeping badly.','fight:private_security',3,'{"cash":40000,"xp":260}'::jsonb,6),
('developer',3,'The Developer','The Developer',15,'A man in a very good suit is buying up Old Town to knock it down. Aunty Rose''s dairy is on his list.','His money','Hit his armoured vans where the rents are collected.','Two months of rent, gone. His lenders start calling.','job:armour',3,'{"cash":60000,"xp":300}'::jsonb,6),
('developer',4,'The Developer','The Developer',15,'A man in a very good suit is buying up Old Town to knock it down. Aunty Rose''s dairy is on his list.','His secret','Sell the city what you know about his deals.','His share price drops thirty percent before lunch.','job:insider',2,'{"cash":80000,"xp":360}'::jsonb,6),
('developer',5,'The Developer','The Developer',15,'A man in a very good suit is buying up Old Town to knock it down. Aunty Rose''s dairy is on his list.','Him','The Developer wants to talk, face to face, in his penthouse. He''s brought friends.','The demolition is called off. Aunty Rose puts your photo behind the counter, next to the Queen.','fight:the_developer',1,'{"cash":200000,"item":"safebox","qty":1,"xp":600}'::jsonb,6),
('airport',1,'Departures','Marlowe, the cargo agent',22,'A cargo agent at the airport moves things that don''t appear on any manifest, and she''s short a pair of hands.','Arrivals','"Fly in, look around, don''t touch anything." Get to the airport.','Marlowe meets you at the cargo gate with a lanyard and a hi-vis vest.','travel:airport',1,'{"cash":40000,"xp":300}'::jsonb,7),
('airport',2,'Departures','Marlowe, the cargo agent',22,'A cargo agent at the airport moves things that don''t appear on any manifest, and she''s short a pair of hands.','Pallet swap','"Some pallets need to swap places. Nobody needs to know."','The pallets go to the wrong planes. On purpose.','job:cargo',4,'{"cash":80000,"xp":400}'::jsonb,7),
('airport',3,'Departures','Marlowe, the cargo agent',22,'A cargo agent at the airport moves things that don''t appear on any manifest, and she''s short a pair of hands.','The dog','The customs dog handler has started paying attention to your pallets.','The dog is fine. The dog likes you. The handler is less keen.','fight:customs_dog_handler',2,'{"cash":90000,"xp":450}'::jsonb,7),
('airport',4,'Departures','Marlowe, the cargo agent',22,'A cargo agent at the airport moves things that don''t appear on any manifest, and she''s short a pair of hands.','Carry-on','"Diamonds. In the lining of a suitcase. Walk them through customs."','You walk straight past three customs officers with $4 million in your luggage.','job:diamonds',3,'{"cash":150000,"xp":550}'::jsonb,7),
('airport',5,'Departures','Marlowe, the cargo agent',22,'A cargo agent at the airport moves things that don''t appear on any manifest, and she''s short a pair of hands.','The Smuggler Queen','Marlowe''s boss wants to meet you. Then she wants you gone.','Marlowe runs the airport now. Your luggage is never searched again.','fight:the_smuggler_queen',1,'{"cash":400000,"item":"safebox","qty":2,"xp":900}'::jsonb,7),
('island',1,'The Big One','Nobody, a voice on the phone',30,'Someone who calls themselves Nobody has a plan to rob Casino Island, the most guarded place in the country. They need the best. That''s you.','The crossing','"Take the ferry. Bring nothing. Wear something nice."','The island glows like a jewellery box in the dark.','travel:island',1,'{"cash":150000,"xp":700}'::jsonb,8),
('island',2,'The Big One','Nobody, a voice on the phone',30,'Someone who calls themselves Nobody has a plan to rob Casino Island, the most guarded place in the country. They need the best. That''s you.','Rig the table','"The high-roller table pays for the operation. Make it pay."','The pit bosses start to sweat. The house is losing.','job:highroller',4,'{"cash":300000,"xp":900}'::jsonb,8),
('island',3,'The Big One','Nobody, a voice on the phone',30,'Someone who calls themselves Nobody has a plan to rob Casino Island, the most guarded place in the country. They need the best. That''s you.','The enforcers','"The casino''s enforcers have a list. You''re on it."','The list gets shorter. Your name comes off it.','fight:casino_enforcer',3,'{"cash":300000,"xp":1000}'::jsonb,8),
('island',4,'The Big One','Nobody, a voice on the phone',30,'Someone who calls themselves Nobody has a plan to rob Casino Island, the most guarded place in the country. They need the best. That''s you.','The gold','"Under the casino there''s a vault. Under the vault there''s another vault."','Bars of gold, stacked to the ceiling. You take what you can carry, which is a lot.','job:gold',2,'{"cash":700000,"xp":1400}'::jsonb,8),
('island',5,'The Big One','Nobody, a voice on the phone',30,'Someone who calls themselves Nobody has a plan to rob Casino Island, the most guarded place in the country. They need the best. That''s you.','The Big One','"Now the real job. The one they''ll make films about." The Owner of the Island is waiting.','The phone rings one last time. "Thank you," says Nobody, in a voice you''ve heard every day of your life on the Waterfront. Aunty Rose hangs up before you can say anything.','job:bigone',1,'{"cash":2000000,"item":"safebox","qty":3,"xp":3000}'::jsonb,8)
insert into game.seasons(id,name,blurb,from_m,from_d,to_m,to_d,points,icon) values
('heatwave','Summer Heatwave','Forty degrees in the shade. Tempers short, windows open, and nobody guarding anything properly.',1,6,2,9,'{"job":1,"fight_win":3,"bust":2,"train":0.1}'::jsonb,'Sun'),
('storms','Winter Storms','Gales off the harbour knock the power out every night. Dark streets, wet alarms, rich pickings.',6,20,7,20,'{"job":1,"fight_win":3,"bust":3,"use":1}'::jsonb,'CloudLightning'),
('halloween','Halloween Night','Masks everywhere, so nobody can tell who''s trick-or-treating and who''s robbing the place.',10,24,10,31,'{"job":1,"fight_win":3,"bust":2}'::jsonb,'Ghost'),
('fireworks','Fireworks Week','Rockets every night for a week. Nobody hears a window break, and every alarm sounds like a bang.',11,1,11,10,'{"job":1,"fight_win":3,"bust":2,"market":1}'::jsonb,'Sparkles'),
('christmas','The Christmas Heist','Every shop is full, every courier is late, and every warehouse is stacked to the roof with presents.',12,10,12,26,'{"job":1,"fight_win":2,"bust":3,"use":1,"market":1}'::jsonb,'Gift')
insert into game.company_types(id,name,cost,lvl,base,perk,max,blurb,sort) values
('coffee','Coffee cart',50000,5,300,'regen',0.1,'Flat whites at the ferry terminal. Staff get free coffee, which turns out to matter.',1),
('carwash','Hand car wash',120000,6,500,'travel_time',0.3,'Ten dollars a wash and no questions about what''s in the boot. Staff learn every shortcut in town.',2),
('tattoo','Tattoo parlour',250000,8,800,'mug',0.25,'The ink says you''re not to be messed with. Muggers read it and keep walking.',3),
('boxing','Boxing gym',500000,10,1200,'gym',0.15,'Ropes, sweat and a coach who used to fight for money. Staff train for free.',4),
('clinic','Private clinic',1500000,14,2200,'hosp',0.3,'Discreet medicine, cash only. Staff get patched up first and fastest.',5),
('lawfirm','Law firm',2500000,16,3500,'jail',0.3,'Three partners, one very expensive receptionist. Staff never spend long in the cells.',6),
('nightclub','Nightclub',5000000,18,6000,'job',5,'Velvet rope, loud bass, and a back office where the real business gets done.',7),
('logistics','Logistics company',10000000,21,10000,'travel_disc',0.6,'Trucks, vans and a warehouse at the Docks. Staff ride anywhere on the company account.',8),
('tech','Tech startup',25000000,25,20000,'listings',15,'An app, a pitch deck and a lot of investors'' money. Staff get a slick storefront on the market.',9),
('media','Media empire',60000000,30,40000,'heat',0.5,'Newspapers, radio and a TV channel. Staff are never in the news for the wrong reasons.',10)
